import{_ as a,o as _,a as c,b as t}from"./app.CIoiBgkh.js";const h=JSON.parse('{"title":"","description":"","frontmatter":{"breadcrumbs":[{"text":"Ascend C API","link":"/api/api_list"},{"text":"附录","link":"/api/appendix/appendix"},{"text":"Release Notes","link":"/api/appendix/Release_Notes/release_notes"},{"text":"CANN 9.2.0","link":"/api/appendix/Release_Notes/CANN_9_2_0"}]},"headers":[],"relativePath":"api/appendix/Release_Notes/CANN_9_2_0.md","filePath":"api/appendix/Release_Notes/CANN_9_2_0.md","outlineHeaders":[{"level":2,"title":"新增特性","slug":"新增特性","link":"#新增特性"},{"level":3,"title":"系统、缓存与控制","slug":"系统、缓存与控制","link":"#系统、缓存与控制"},{"level":3,"title":"矩阵计算与数据搬运","slug":"矩阵计算与数据搬运","link":"#矩阵计算与数据搬运"},{"level":3,"title":"标量计算","slug":"标量计算","link":"#标量计算"},{"level":3,"title":"Memory矢量计算","slug":"Memory矢量计算","link":"#Memory矢量计算"},{"level":3,"title":"Reg计算与Reg数据搬运","slug":"Reg计算与Reg数据搬运","link":"#Reg计算与Reg数据搬运"},{"level":2,"title":"增强","slug":"增强","link":"#增强"},{"level":3,"title":"Reg计算","slug":"Reg计算","link":"#Reg计算"},{"level":3,"title":"矩阵计算与数据搬运","slug":"矩阵计算与数据搬运-1","link":"#矩阵计算与数据搬运-1"},{"level":3,"title":"系统与同步","slug":"系统与同步","link":"#系统与同步"},{"level":3,"title":"公共头文件","slug":"公共头文件","link":"#公共头文件"},{"level":2,"title":"Bug修复","slug":"Bug修复","link":"#Bug修复"},{"level":2,"title":"接口废弃","slug":"接口废弃","link":"#接口废弃"},{"level":2,"title":"文件废弃","slug":"文件废弃","link":"#文件废弃"}],"lastUpdated":1789543187000}'),d={name:"api/appendix/Release_Notes/CANN_9_2_0.md"};function s(o,e,r,l,i,p){return _(),c("div",null,[...e[0]||(e[0]=[t('<div><article class="markdown-body"><h1>C API</h1><p>CANN 9.2.0在CANN 9.1.0的基础上继续增强C API。本版本新增矩阵与数据搬运配置、Reg计算与搬运、缓存和特殊寄存器控制等能力，为大量Reg接口补充函数返回值形式的重载，并统一公共头文件、接口命名和参数类型。同时，部分旧命名、隐式位置重载和同步复合接口进入废弃期。</p><h2 id="新增特性">新增特性<a class="header-anchor" href="#新增特性">​</a></h2><h3 id="系统、缓存与控制">系统、缓存与控制<a class="header-anchor" href="#系统、缓存与控制">​</a></h3><ul><li><a href="../../SIMD-API/c_api/atomic/datamove_atomic/asc_disable_dma_atomic.html">asc_disable_dma_atomic</a>：在完成数据搬运原子操作后关闭原子操作，避免已开启的原子操作影响后续搬运。该接口支持Atlas A2 训练系列产品/Atlas A2 推理系列产品和Atlas A3 训练系列产品/Atlas A3 推理系列产品，以及Ascend 950PR/Ascend 950DT。</li><li><a href="../../SIMD-API/c_api/atomic/datamove_atomic/asc_set_atomic_add.html">asc_set_atomic_add_int32</a>、<a href="../../SIMD-API/c_api/atomic/datamove_atomic/asc_set_atomic_max.html">asc_set_atomic_max_int32</a>和<a href="../../SIMD-API/c_api/atomic/datamove_atomic/asc_set_atomic_min.html">asc_set_atomic_min_int32</a>：分别开启数据搬运过程中的<code>int32_t</code>原子加、原子最大值和原子最小值操作，使用明确的数据类型后缀替代旧的<code>*_int</code>命名。该组接口支持Atlas A2 训练系列产品/Atlas A2 推理系列产品和Atlas A3 训练系列产品/Atlas A3 推理系列产品，以及Ascend 950PR/Ascend 950DT。</li><li><a href="../../SIMD-API/c_api/experimental/asc_get_pipe_idle_slot_count.html">asc_get_pipe_mte2_idle_slot_count</a>、<a href="../../SIMD-API/c_api/experimental/asc_get_pipe_idle_slot_count.html">asc_get_pipe_mte3_idle_slot_count</a>、<a href="../../SIMD-API/c_api/experimental/asc_get_pipe_idle_slot_count.html">asc_get_pipe_v_idle_slot_count</a>、<a href="../../SIMD-API/c_api/experimental/asc_get_pipe_idle_slot_count.html">asc_get_pipe_m_idle_slot_count</a>、<a href="../../SIMD-API/c_api/experimental/asc_get_pipe_idle_slot_count.html">asc_get_pipe_mte1_idle_slot_count</a>和<a href="../../SIMD-API/c_api/experimental/asc_get_pipe_idle_slot_count.html">asc_get_pipe_fix_idle_slot_count</a>：分别查询PIPE_MTE2、PIPE_MTE3、PIPE_V、PIPE_M、PIPE_MTE1和PIPE_FIX发射队列当前的空闲槽位数量，用于观察队列还能接收的待发射指令数量。该组接口仅支持Ascend 950PR/Ascend 950DT，属于试验特性，使用时需包含<code>c_api/experimental/asc_get_pipe_idle_slot_count.h</code>并定义<code>CANN_ASC_USE_EXPERIMENTAL</code>。</li><li><a href="../../SIMD-API/c_api/cache_ctrl/asc_set_scalar_cache_mode.html">asc_set_scalar_cache_mode</a>、<a href="../../SIMD-API/c_api/cache_ctrl/asc_get_scalar_load_cache_mode.html">asc_get_scalar_load_cache_mode</a>、<a href="../../SIMD-API/c_api/cache_ctrl/asc_get_scalar_store_cache_mode.html">asc_get_scalar_store_cache_mode</a>：支持分别设置标量读、写Global Memory时的L2 Cache管理策略，以及回读当前的标量读、写策略。设置后的策略持续生效，直至再次调用设置接口修改。该组接口仅支持Ascend 950PR/Ascend 950DT。</li><li><a href="../../SIMD-API/c_api/spr/asc_set_saturation_flag.html">asc_set_saturation_flag</a>和<a href="../../SIMD-API/c_api/spr/asc_get_saturation_flag.html">asc_get_saturation_flag</a>：支持通过<a href="../../SIMD-API/c_api/defs/enum/asc_saturation_mode.html">asc_saturation_mode</a>设置或查询浮点、FP8、整数和类型转换场景的饱和开关；<a href="../../SIMD-API/c_api/spr/asc_set_saturation_strategy.html">asc_set_saturation_strategy</a>和<a href="../../SIMD-API/c_api/spr/asc_get_saturation_strategy.html">asc_get_saturation_strategy</a>支持通过<a href="../../SIMD-API/c_api/defs/enum/asc_override_strategy.html">asc_override_strategy</a>在单指令/API路径配置与全局饱和配置之间切换和查询。其中，类型转换场景的全局饱和开关仅在使用全局饱和配置时生效。该组接口仅支持Ascend 950PR/Ascend 950DT。</li><li><a href="../../SIMD-API/c_api/utils/sys_var/asc_get_system_clock.html">asc_get_system_clock</a>：读取当前系统cycle计数器，按芯片时钟频率换算后直接返回<code>int64_t</code>类型的微秒级时间值，在AIC和AIV上的返回值含义一致。CANN 9.1.0中已有的<a href="../../SIMD-API/c_api/utils/sys_var/asc_get_system_cycle.html">asc_get_system_cycle</a>仍用于读取原始cycle计数值。该接口支持Atlas A2 训练系列产品/Atlas A2 推理系列产品和Atlas A3 训练系列产品/Atlas A3 推理系列产品，以及Ascend 950PR/Ascend 950DT。</li><li><a href="../../SIMD-API/c_api/utils/sys_misc/asc_nop.html">asc_nop</a>：生成一条空操作指令，不执行实际计算。每调用一次阻塞一拍流水。该接口仅支持Ascend 950PR/Ascend 950DT。</li></ul><h3 id="矩阵计算与数据搬运">矩阵计算与数据搬运<a class="header-anchor" href="#矩阵计算与数据搬运">​</a></h3><ul><li><a href="../../SIMD-API/c_api/cube_compute/asc_disable_hf32.html">asc_disable_hf32</a>：关闭Mmad计算的HF32模式，使L0A Buffer和L0B Buffer中的<code>float</code>数据在参与计算前不做舍入处理；<a href="../../SIMD-API/c_api/cube_compute/asc_disable_hif8.html">asc_disable_hif8</a>：关闭HiF8模式，使左右矩阵均为<code>fp8_e4m3fn_t</code>时不再转换为<code>hifloat8_t</code>，而是直接参与矩阵乘法。两个接口均为仅在AIC上生效的矩阵计算配置接口。其中，<code>asc_disable_hf32</code>支持Atlas A2 训练系列产品/Atlas A2 推理系列产品和Atlas A3 训练系列产品/Atlas A3 推理系列产品，以及Ascend 950PR/Ascend 950DT，<code>asc_disable_hif8</code>仅支持Ascend 950PR/Ascend 950DT。</li><li><a href="../../SIMD-API/c_api/cube_compute/asc_set_hf32_round_mode.html">asc_set_hf32_round_mode</a>：使用<a href="../../SIMD-API/c_api/defs/enum/asc_hf32_round_mode.html">asc_hf32_round_mode</a>枚举配置HF32舍入方式，调用前需先开启HF32模式。该接口支持Atlas A2 训练系列产品/Atlas A2 推理系列产品和Atlas A3 训练系列产品/Atlas A3 推理系列产品，以及Ascend 950PR/Ascend 950DT。</li><li><a href="../../SIMD-API/c_api/cube_datamove/asc_set_gm2l1_padding.html">asc_set_gm2l1_padding</a>：配置GM到L1 Buffer高维切分搬运的Padding值；<a href="../../SIMD-API/c_api/cube_datamove/asc_set_l12l0a_3d_padding.html">asc_set_l12l0a_3d_padding</a>和<a href="../../SIMD-API/c_api/cube_datamove/asc_set_l12l0b_3d_padding.html">asc_set_l12l0b_3d_padding</a>：分别配置左、右矩阵3D im2col搬运的填充值；<a href="../../SIMD-API/c_api/cube_datamove/asc_set_l13d_rpt_b.html">asc_set_l13d_rpt_b</a>：配置3D im2col模式下右矩阵使用repeat搬运所需的参数。该组接口均仅在AIC上生效；其中，<code>asc_set_gm2l1_padding</code>和<code>asc_set_l12l0a_3d_padding</code>同时支持Atlas A2 训练系列产品/Atlas A2 推理系列产品和Atlas A3 训练系列产品/Atlas A3 推理系列产品，以及Ascend 950PR/Ascend 950DT，其余接口仅支持Ascend 950PR/Ascend 950DT。</li><li><a href="../../SIMD-API/c_api/cube_datamove/asc_set_l0c_copy_config.html">asc_set_l0c_copy_config</a>：配置L0C Buffer搬出时随路Tensor量化、Tensor激活参数在Fixpipe Buffer中的起始索引，并支持初始化UnitFlag全局状态；<a href="../../SIMD-API/c_api/cube_datamove/asc_set_l0c_copy_channel_para.html">asc_set_l0c_copy_channel_para</a>：配置Nz2DN格式转换时源Nz矩阵相邻行的地址偏移；<a href="../../SIMD-API/c_api/cube_datamove/asc_set_l0c_copy_nz_para.html">asc_set_l0c_copy_nz_para</a>：配置随路Nz转ND/DN所需参数；<a href="../../SIMD-API/c_api/cube_datamove/asc_set_l0c_copy_relu_alpha.html">asc_set_l0c_copy_relu_alpha</a>和<a href="../../SIMD-API/c_api/cube_datamove/asc_set_l0c_copy_lrelu_alpha.html">asc_set_l0c_copy_lrelu_alpha</a>：配置随路Scalar激活的缩放系数。该组配置由后续L0C Buffer搬出接口使用，且仅在AIC上生效。其中，<code>asc_set_l0c_copy_config</code>和<code>asc_set_l0c_copy_lrelu_alpha</code>同时支持Atlas A2 训练系列产品/Atlas A2 推理系列产品和Atlas A3 训练系列产品/Atlas A3 推理系列产品，以及Ascend 950PR/Ascend 950DT，其余接口仅支持Ascend 950PR/Ascend 950DT。新接口<code>asc_set_l0c_copy_lrelu_alpha</code>仅提供<code>float</code>参数形式；CANN 9.1.0已有的<a href="../../SIMD-API/c_api/deprecated_interface/asc_set_l0c2gm_lrelu_alpha_deprecated.html">asc_set_l0c2gm_lrelu_alpha</a>仍提供<code>half&amp;</code>和<code>float&amp;</code>参数形式。</li></ul><h3 id="标量计算">标量计算<a class="header-anchor" href="#标量计算">​</a></h3><ul><li><a href="../../SIMD-API/c_api/scalar_compute/scalar_load/asc_load_dev.html">asc_load_dev</a>：不经过Data Cache直接从Global Memory读取整型标量数据，适用于多核访问无法按Cache Line对齐的GM地址、需要避免Cache Line粒度数据覆盖的场景。该接口仅支持Ascend 950PR/Ascend 950DT。</li><li><a href="../../SIMD-API/c_api/scalar_compute/scalar_convert/asc_float2half.html">asc_float2half_ro</a>：在标量流水上将<code>float</code>转换为<code>half</code>并直接返回结果，舍入模式固定为ODD（最近邻奇数舍入）。该接口仅支持Ascend 950PR/Ascend 950DT。</li></ul><h3 id="Memory矢量计算">Memory矢量计算<a class="header-anchor" href="#Memory矢量计算">​</a></h3><ul><li><a href="../../SIMD-API/c_api/vector_compute/vector_permute_sel/asc_transto5hd.html">asc_transto5hd</a>：将<a href="../../SIMD-API/c_api/vector_compute/vector_permute_sel/asc_transto5hd.html">asc_transto5hd_b8</a>、<a href="../../SIMD-API/c_api/vector_compute/vector_permute_sel/asc_transto5hd.html">asc_transto5hd_b16</a>和<a href="../../SIMD-API/c_api/vector_compute/vector_permute_sel/asc_transto5hd.html">asc_transto5hd_b32</a>正式加入公共头文件，用于NCHW到NC1HWC0格式转换或二维矩阵数据块转置。单次Repeat处理512 Byte（16个DataBlock），并支持多次Repeat操作。该组接口支持Atlas A2 训练系列产品/Atlas A2 推理系列产品和Atlas A3 训练系列产品/Atlas A3 推理系列产品，以及Ascend 950PR/Ascend 950DT。</li><li><a href="../../SIMD-API/c_api/vector_compute/vector_mask_config/asc_set_vector_mask.html">asc_set_vector_mask</a>新增Ascend 950PR/Ascend 950DT支持，可在Vector Function外配置掩码寄存器，并配合Reg矢量计算接口使用。</li></ul><h3 id="Reg计算与Reg数据搬运">Reg计算与Reg数据搬运<a class="header-anchor" href="#Reg计算与Reg数据搬运">​</a></h3><p>本节新增接口均仅支持Ascend 950PR/Ascend 950DT，并在AIV的Vector Function中调用。</p><ul><li><a href="../../SIMD-API/c_api/reg_compute/reg_broadcast/asc_duplicate_highest.html">asc_duplicate_highest</a>和<a href="../../SIMD-API/c_api/reg_compute/reg_broadcast/asc_duplicate_highest_merge.html">asc_duplicate_highest_merge</a>：将源操作数中下标最大的元素广播到被掩码选中的目的位置，未选中位置分别置0或保留原值；<a href="../../SIMD-API/c_api/reg_compute/reg_broadcast/asc_duplicate_merge.html">asc_duplicate_merge</a>和<a href="../../SIMD-API/c_api/reg_compute/reg_broadcast/asc_duplicate_scalar_merge.html">asc_duplicate_scalar_merge</a>：分别将源操作数中下标最小的元素或给定标量广播到被掩码选中的目的位置，并保留未选中位置的原值。</li><li><a href="../../SIMD-API/c_api/reg_compute/reg_copy/asc_mask.html">asc_mask</a>：支持通过函数返回值完成矢量数据寄存器或掩码寄存器的掩码复制；<a href="../../SIMD-API/c_api/reg_compute/reg_copy/asc_extract_mask.html">asc_extract_mask</a>：从<code>uint16_t</code>或<code>uint32_t</code>矢量数据寄存器的指定数据块中提取并扩展bit，生成掩码寄存器返回值。</li><li><a href="../../SIMD-API/c_api/reg_compute/reg_permute_sel/asc_pack_to_low.html">asc_pack_to_low</a>和<a href="../../SIMD-API/c_api/reg_compute/reg_permute_sel/asc_pack_to_high.html">asc_pack_to_high</a>：选取源操作数的偶数bit（<code>vector_bool</code>）、低8位（b16）或低16位（b32），并分别写入目的操作数的低半部分或高半部分。</li><li><a href="../../SIMD-API/c_api/reg_compute/reg_permute_sel/asc_unsqueeze.html">asc_unsqueeze</a>新增<a href="../../SIMD-API/c_api/reg_compute/reg_permute_sel/asc_unsqueeze.html">asc_unsqueeze_s8</a>、<a href="../../SIMD-API/c_api/reg_compute/reg_permute_sel/asc_unsqueeze.html">asc_unsqueeze_u8</a>、<a href="../../SIMD-API/c_api/reg_compute/reg_permute_sel/asc_unsqueeze.html">asc_unsqueeze_s16</a>、<a href="../../SIMD-API/c_api/reg_compute/reg_permute_sel/asc_unsqueeze.html">asc_unsqueeze_u16</a>、<a href="../../SIMD-API/c_api/reg_compute/reg_permute_sel/asc_unsqueeze.html">asc_unsqueeze_s32</a>和<a href="../../SIMD-API/c_api/reg_compute/reg_permute_sel/asc_unsqueeze.html">asc_unsqueeze_u32</a>，支持通过函数返回值获取掩码前缀计数结果：首元素为0，第<code>i</code>个元素为掩码第0至第<code>i-1</code>个元素中1的数量，掩码最高位不参与统计。</li><li><a href="../../SIMD-API/c_api/reg_compute/reg_fused/asc_fma.html">asc_fma</a>、<a href="../../SIMD-API/c_api/reg_compute/reg_fused/asc_mula.html">asc_mula</a>和<a href="../../SIMD-API/c_api/reg_compute/reg_fused/asc_mul_scalar_float2half_rn.html">asc_mul_scalar_float2half_rn</a>：分别支持三源融合乘加、目的操作数作为累加器参与乘加，以及<code>float</code>矢量与标量相乘后按RINT模式转换为<code>half</code>并写入指定奇偶位置。其中，<code>asc_fma</code>在CANN 9.1.0中仅有Memory矢量计算接口，本版本新增的是Reg接口。</li><li><a href="../../SIMD-API/c_api/reg_compute/reg_fused/asc_exp_sub.html">asc_exp_sub</a>新增<a href="../../SIMD-API/c_api/reg_compute/reg_fused/asc_exp_sub.html">asc_exp_sub_half2float</a>接口，支持显式选择<code>half</code>源操作数的奇数或偶数索引元素，转换为<code>float</code>后逐元素计算以两源差值为指数的自然指数函数；<a href="../../SIMD-API/c_api/reg_compute/reg_arith/asc_log.html">asc_log</a>新增Reg逐元素自然对数计算接口。</li><li><a href="../../SIMD-API/c_api/reg_compute/reg_permute_sel/asc_squeeze_and_storeunalign_init.html">asc_squeeze_and_storeunalign_init</a>清零AR特殊寄存器；<a href="../../SIMD-API/c_api/reg_compute/reg_permute_sel/asc_squeeze_and_storeunalign.html">asc_squeeze_and_storeunalign</a>按掩码筛选矢量寄存器元素，将结果连续搬出到非32字节对齐的UB地址，并在AR寄存器中累计有效数据总字节数；<a href="../../SIMD-API/c_api/reg_compute/reg_permute_sel/asc_squeeze_and_storeunalign_finalize.html">asc_squeeze_and_storeunalign_finalize</a>将不足32 Byte、暂存在非对齐寄存器中的尾块写入UB。</li><li><a href="../../SIMD-API/c_api/spr/asc_get_squeeze_status.html">asc_get_squeeze_status</a>：读取squeeze操作保存在AR特殊寄存器中的有效数据长度；<a href="../../SIMD-API/c_api/reg_compute/store/asc_storealign_squeeze_status.html">asc_storealign_squeeze_status</a>和<a href="../../SIMD-API/c_api/reg_compute/store/asc_storealign_squeeze_status_postupdate.html">asc_storealign_squeeze_status_postupdate</a>：将该长度搬出到UB，后者还会在写入后按字节偏移自动更新目的地址。</li><li>Reg对齐搬入新增语义明确的模式接口：<a href="../../SIMD-API/c_api/reg_compute/load/asc_loadalign_brc_datablock.html">asc_loadalign_brc_datablock</a>广播一个32 Byte DataBlock，<a href="../../SIMD-API/c_api/reg_compute/load/asc_loadalign_brc_elem.html">asc_loadalign_brc_elem</a>广播一个元素，<a href="../../SIMD-API/c_api/reg_compute/load/asc_loadalign_brc_elem2datablock.html">asc_loadalign_brc_elem2datablock</a>连续读取8个元素并将每个元素广播为一个DataBlock，<a href="../../SIMD-API/c_api/reg_compute/load/asc_loadalign_unpack4.html">asc_loadalign_unpack4</a>读取VL/4长度数据并在每个元素后补3个0；对应的<a href="../../SIMD-API/c_api/reg_compute/load/asc_loadalign_brc_datablock_postupdate.html">asc_loadalign_brc_datablock_postupdate</a>、<a href="../../SIMD-API/c_api/reg_compute/load/asc_loadalign_brc_elem_postupdate.html">asc_loadalign_brc_elem_postupdate</a>、<a href="../../SIMD-API/c_api/reg_compute/load/asc_loadalign_brc_elem2datablock_postupdate.html">asc_loadalign_brc_elem2datablock_postupdate</a>和<a href="../../SIMD-API/c_api/reg_compute/load/asc_loadalign_unpack4_postupdate.html">asc_loadalign_unpack4_postupdate</a>在搬入后自动更新源地址。新增<a href="../../SIMD-API/c_api/reg_compute/load/asc_loadalign_datablock_strided.html">asc_loadalign_datablock_strided</a>、<a href="../../SIMD-API/c_api/reg_compute/load/asc_loadalign_mask.html">asc_loadalign_mask</a>、<a href="../../SIMD-API/c_api/reg_compute/load/asc_loadalign_mask_downsample.html">asc_loadalign_mask_downsample</a>和<a href="../../SIMD-API/c_api/reg_compute/load/asc_loadalign_mask_upsample.html">asc_loadalign_mask_upsample</a>返回值接口，分别支持跨步搬入8个DataBlock，以及直接返回原始、偶数bit下采样和bit二倍重复上采样的掩码寄存器。</li><li><a href="../../SIMD-API/c_api/reg_compute/store/asc_storealign_pack_quarter.html">asc_storealign_pack_quarter</a>和<a href="../../SIMD-API/c_api/reg_compute/store/asc_storealign_pack_quarter_postupdate.html">asc_storealign_pack_quarter_postupdate</a>：按掩码将32位Reg有效元素的低8位压缩搬出到UB，后者在搬出后按偏移自动更新目的地址。</li><li><a href="../../SIMD-API/c_api/reg_compute/reg_addr_reg/asc_update_addr_reg.html">asc_update_addr_reg</a>接口族新增<a href="../../SIMD-API/c_api/reg_compute/reg_addr_reg/asc_update_addr_reg.html">asc_update_addr_reg_b8</a>、<a href="../../SIMD-API/c_api/reg_compute/reg_addr_reg/asc_update_addr_reg.html">asc_update_addr_reg_b16</a>和<a href="../../SIMD-API/c_api/reg_compute/reg_addr_reg/asc_update_addr_reg.html">asc_update_addr_reg_b32</a>，分别按1 Byte、2 Byte和4 Byte为单位计算1至4维循环的地址偏移，使用<a href="../../SIMD-API/c_api/defs/type/data_type_definition.html#%E5%9C%B0%E5%9D%80%E5%AF%84%E5%AD%98%E5%99%A8">addr_reg</a>保存偏移并配合Reg搬入、搬出接口完成迭代寻址，替代原<a href="../../SIMD-API/c_api/deprecated_interface/asc_create_iter_reg_deprecated.html">iter_reg</a>接口族。</li></ul><h2 id="增强">增强<a class="header-anchor" href="#增强">​</a></h2><h3 id="Reg计算">Reg计算<a class="header-anchor" href="#Reg计算">​</a></h3><ul><li>为Reg算术、比较、逻辑、融合、规约、广播、索引生成、类型转换、数据搬入和排布变换接口补充函数返回值形式的重载。涉及<a href="../../SIMD-API/c_api/reg_compute/reg_arith/asc_add.html">asc_add</a>、<a href="../../SIMD-API/c_api/reg_compute/reg_arith/asc_sub.html">asc_sub</a>、<a href="../../SIMD-API/c_api/reg_compute/reg_arith/asc_mul.html">asc_mul</a>、<a href="../../SIMD-API/c_api/reg_compute/reg_arith/asc_div.html">asc_div</a>、<a href="../../SIMD-API/c_api/reg_compute/reg_arith/asc_max.html">asc_max</a>、<a href="../../SIMD-API/c_api/reg_compute/reg_arith/asc_min.html">asc_min</a>、<a href="../../SIMD-API/c_api/reg_compute/reg_arith/asc_abs.html">asc_abs</a>、<a href="../../SIMD-API/c_api/reg_compute/reg_arith/asc_neg.html">asc_neg</a>、<a href="../../SIMD-API/c_api/reg_compute/reg_arith/asc_sqrt.html">asc_sqrt</a>、<a href="../../SIMD-API/c_api/reg_compute/reg_arith/asc_exp.html">asc_exp</a>、比较与标量比较接口、<a href="../../SIMD-API/c_api/reg_compute/reg_logic/asc_and.html">asc_and</a>、<a href="../../SIMD-API/c_api/reg_compute/reg_logic/asc_or.html">asc_or</a>、<a href="../../SIMD-API/c_api/reg_compute/reg_logic/asc_not.html">asc_not</a>、<a href="../../SIMD-API/c_api/reg_compute/reg_logic/asc_xor.html">asc_xor</a>、移位接口、<a href="../../SIMD-API/c_api/reg_compute/reg_fused/asc_abs_sub.html">asc_abs_sub</a>、<a href="../../SIMD-API/c_api/reg_compute/reg_fused/asc_relu.html">asc_relu</a>、规约接口、<a href="../../SIMD-API/c_api/reg_compute/reg_broadcast/asc_duplicate.html">asc_duplicate</a>、<a href="../../SIMD-API/c_api/reg_compute/reg_broadcast/asc_duplicate_scalar.html">asc_duplicate_scalar</a>、<a href="../../SIMD-API/c_api/reg_compute/reg_index/asc_arange.html">asc_arange</a>、<a href="../../SIMD-API/c_api/reg_compute/reg_index/asc_arange.html">asc_arange_descend</a>、<a href="../../SIMD-API/c_api/reg_compute/load/asc_load.html">asc_load</a>、<a href="../../SIMD-API/c_api/reg_compute/load/asc_loadalign.html">asc_loadalign</a>、<a href="../../SIMD-API/c_api/reg_compute/ub_gather/asc_gather_datablock.html">asc_gather_datablock</a>、<a href="../../SIMD-API/c_api/reg_compute/reg_convert/asc_half2int16.html">asc_half2int16</a>及其他Reg类型转换接口。</li><li><code>asc_div</code>新增<code>int16_t</code>、<code>uint16_t</code>、<code>int32_t</code>和<code>uint32_t</code>重载；寄存器源<a href="../../SIMD-API/c_api/reg_compute/reg_gather/asc_gather.html">asc_gather</a>新增<code>vector_float</code>重载，UB源<a href="../../SIMD-API/c_api/reg_compute/ub_gather/asc_gather.html">asc_gather</a>新增<code>int8_t</code>和<code>uint8_t</code>同宽输出重载。两类接口的资料和头文件归属同步拆分：UB源收集接口使用<code>c_api/reg_compute/gather/ub_gather.h</code>，寄存器源收集接口使用<code>c_api/reg_compute/compute/reg_gather.h</code>。</li><li>Reg搬入、搬出接口的迭代偏移参数由<code>iter_reg</code>迁移为<code>addr_reg</code>，与本版本新增的<code>asc_update_addr_reg_b8</code>、<code>asc_update_addr_reg_b16</code>和<code>asc_update_addr_reg_b32</code>配合完成循环寻址。</li><li><a href="../../SIMD-API/c_api/reg_compute/reg_arith/asc_min_scalar.html">asc_min_scalar</a>和<a href="../../SIMD-API/c_api/reg_compute/reg_compare/asc_ne.html">asc_ne</a>新增<code>bfloat16_t</code>重载。</li><li><code>asc_duplicate</code>、<code>asc_duplicate_scalar</code>新增<code>fp8_e8m0_t</code>引用输出重载，并补充包括<code>fp8_e8m0_t</code>在内的函数返回值形式；<a href="../../SIMD-API/c_api/reg_compute/reg_fused/asc_madd.html">asc_madd</a>新增<code>bfloat16_t</code>重载。</li><li><a href="../../SIMD-API/c_api/reg_compute/store/asc_store.html">asc_store</a>补充<code>half</code>数据类型且带<code>count</code>参数的公共重载，支持指定从Reg搬出到UB的有效元素数量。</li><li>类型转换接口补充显式源/目的位置参数和函数返回值形式，统一由<a href="../../SIMD-API/c_api/defs/enum/asc_position_mode.html">asc_position_mode</a>或<a href="../../SIMD-API/c_api/defs/enum/asc_position_quarter_mode.html">asc_position_quarter_mode</a>表达位置；奇偶位置也可直接使用<a href="../../SIMD-API/c_api/defs/enum/asc_position_mode.html">ASC_POSITION_EVEN</a>和<a href="../../SIMD-API/c_api/defs/enum/asc_position_mode.html">ASC_POSITION_ODD</a>常量，不再依赖<code>_v2</code>、<code>_v3</code>、<code>_v4</code>后缀推断位置。</li><li><a href="../../SIMD-API/c_api/reg_compute/reg_convert/asc_half2int4x2.html">asc_half2int4x2</a>、<a href="../../SIMD-API/c_api/reg_compute/reg_convert/asc_int4x22int16.html">asc_int4x22int16</a>、<a href="../../SIMD-API/c_api/reg_compute/reg_convert/asc_int4x22half.html">asc_int4x22half</a>和<a href="../../SIMD-API/c_api/reg_compute/reg_convert/asc_int4x22bfloat16.html">asc_int4x22bfloat16</a>新增显式四分之一位置标签重载，通过<code>asc_position_quarter_mode</code>的四种位置值选择<code>vector_int4x2_t</code>目的或源操作数的第1至第4个四分之一区域。<code>half</code>转<code>int4x2</code>支持FLOOR、RINT、ROUND、CEIL和TRUNC五种舍入模式，每种模式均提供饱和与非饱和形式；这些重载均无返回值，通过<code>dst</code>引用输出结果，仅支持Ascend 950PR/Ascend 950DT并在AIV的Vector Function中调用。</li></ul><h3 id="矩阵计算与数据搬运-1">矩阵计算与数据搬运<a class="header-anchor" href="#矩阵计算与数据搬运-1">​</a></h3><ul><li><a href="../../SIMD-API/c_api/cube_compute/asc_mmad.html">asc_mmad</a>和<a href="../../SIMD-API/c_api/cube_compute/asc_mmad_mx.html">asc_mmad_mx</a>新增显式传入Bias起始地址的重载，支持使用BiasTable Buffer中的Bias矩阵初始化结果矩阵。新增重载仅支持Ascend 950PR/Ascend 950DT。</li><li><a href="../../SIMD-API/c_api/cube_datamove/asc_copy_gm2l1/asc_copy_gm2l1.html">asc_copy_gm2l1</a>、<a href="../../SIMD-API/c_api/cube_datamove/asc_copy_gm2l1_align.html">asc_copy_gm2l1_align</a>、<a href="../../SIMD-API/c_api/cube_datamove/asc_copy_gm2l1_nd2nz/asc_copy_gm2l1_nd2nz.html">asc_copy_gm2l1_nd2nz</a>、<a href="../../SIMD-API/c_api/cube_datamove/asc_copy_gm2l1_dn2nz.html">asc_copy_gm2l1_dn2nz</a>以及L0C Buffer搬出接口补充参数化重载，支持使用枚举配置L2 Cache、量化、激活、格式转换和UnitFlag等搬运行为。新增的强类型重载仅支持Ascend 950PR/Ascend 950DT。</li><li><a href="../../SIMD-API/c_api/cube_datamove/asc_copy_l0c2l1/asc_copy_l0c2l1.html">asc_copy_l0c2l1</a>补充Ascend 950PR/Ascend 950DT的矩阵搬出重载及随路配置能力。该接口名在CANN 9.1.0中已经存在，本版本增强的是3510架构的原型和实现。</li><li><a href="../../SIMD-API/c_api/cube_datamove/asc_set_gm2l1_nz_para.html">asc_set_gm2l1_nz_para</a>新增逐项传入矩阵数量和三个Nz目的地址步长的重载；<a href="../../SIMD-API/c_api/cube_datamove/asc_set_l0c_copy_prequant.html">asc_set_l0c_copy_prequant</a>新增逐项传入Scalar量化缩放系数、偏移量和结果符号的重载，调用者无需再自行拼装64位配置值。上述新增重载仅支持Ascend 950PR/Ascend 950DT；<code>asc_set_l0c_copy_prequant(uint64_t config)</code>同时支持Atlas A2 训练系列产品/Atlas A2 推理系列产品和Atlas A3 训练系列产品/Atlas A3 推理系列产品，以及Ascend 950PR/Ascend 950DT。</li><li><a href="../../SIMD-API/c_api/cube_datamove/asc_set_l13d_rpt.html">asc_set_l13d_rpt</a>、<a href="../../SIMD-API/c_api/cube_datamove/asc_set_l13d_fmatrix.html">asc_set_l13d_fmatrix</a>和<a href="../../SIMD-API/c_api/cube_datamove/asc_set_l13d_fmatrix_b.html">asc_set_l13d_fmatrix_b</a>新增参数化重载，分别直接配置3D im2col搬运的repeat步长、次数、方向和目的位置，以及左、右矩阵的Feature Map宽高与四周Padding。上述重载同时支持Atlas A2 训练系列产品/Atlas A2 推理系列产品和Atlas A3 训练系列产品/Atlas A3 推理系列产品，以及Ascend 950PR/Ascend 950DT，仅在AIC上生效。</li><li><a href="../../SIMD-API/c_api/cube_datamove/asc_copy_l12ub.html">asc_copy_l12ub</a>的<code>sub_blockid</code>参数由<code>bool</code>调整为<code>int8_t</code>，明确使用<code>0</code>和<code>1</code>选择目的Vector Core；其余搬运参数名称同步调整为与功能含义一致的<code>burst_count</code>和<code>burst_len</code>。该调整仅涉及Ascend 950PR/Ascend 950DT原型。</li><li><a href="../../SIMD-API/c_api/vector_datamove/asc_copy_gm2ub_align/asc_copy_gm2ub_align.html">asc_copy_gm2ub_align</a>和<a href="../../SIMD-API/c_api/vector_datamove/asc_ndim_copy_gm2ub.html">asc_ndim_copy_gm2ub</a>新增使用<a href="../../SIMD-API/c_api/defs/enum/asc_load_l2_cache_mode.html">asc_load_l2_cache_mode</a>配置L2 Cache策略的重载；<a href="../../SIMD-API/c_api/vector_datamove/asc_copy_ub2gm_align/asc_copy_ub2gm_align.html">asc_copy_ub2gm_align</a>新增使用<a href="../../SIMD-API/c_api/defs/enum/asc_store_l2_cache_mode.html">asc_store_l2_cache_mode</a>配置L2 Cache策略的重载。上述强类型重载仅支持Ascend 950PR/Ascend 950DT。</li><li>矩阵与矢量搬运配置新增<a href="../../SIMD-API/c_api/defs/enum/asc_load_l2_cache_mode.html">asc_load_l2_cache_mode</a>、<a href="../../SIMD-API/c_api/defs/enum/asc_store_l2_cache_mode.html">asc_store_l2_cache_mode</a>、<a href="../../SIMD-API/c_api/defs/enum/asc_channel_pad_mode.html">asc_channel_pad_mode</a>、<a href="../../SIMD-API/c_api/defs/enum/asc_l13d_repeat_direction.html">asc_l13d_repeat_direction</a>、<a href="../../SIMD-API/c_api/defs/enum/asc_unit_flag_mode.html">asc_unit_flag_mode</a>、<a href="../../SIMD-API/c_api/defs/enum/asc_quant_mode.html">asc_quant_mode</a>、<a href="../../SIMD-API/c_api/defs/enum/asc_relu_pre_mode.html">asc_relu_pre_mode</a>和<a href="../../SIMD-API/c_api/defs/enum/asc_dual_dst_mode.html">asc_dual_dst_mode</a>等强类型枚举或别名，减少使用无类型整数配置硬件行为的歧义。</li><li><code>asc_hf32_round_mode</code>统一为<code>NEAREST_AWAY</code>和<code>NEAREST_EVEN</code>。旧枚举值<code>NEAREST_ZERO</code>作为兼容别名保留，其实际行为等同于<code>NEAREST_AWAY</code>。</li></ul><h3 id="系统与同步">系统与同步<a class="header-anchor" href="#系统与同步">​</a></h3><ul><li><a href="../../SIMD-API/c_api/utils/sys_var/asc_get_arch_ver.html">asc_get_arch_ver</a>改为返回Ascend C对外使用的架构版本号，2201架构返回<code>2201</code>，3510架构返回<code>3510</code>，不再直接暴露芯片寄存器中的内部版本字段。</li><li><a href="../../SIMD-API/c_api/sync/asc_sync_pipe.html">asc_sync_pipe</a>补齐2201架构Vector Core的<code>PIPE_V</code>单流水同步，并修正3510架构<a href="../../SIMD-API/c_api/sync/asc_sync_vec.html">asc_sync_vec</a>带<code>id</code>重载中的冗余Vector流水屏障。</li><li><a href="../../SIMD-API/c_api/sync/asc_lock.html">asc_lock</a>和<a href="../../SIMD-API/c_api/sync/asc_unlock.html">asc_unlock</a>新增使用<a href="../../SIMD-API/c_api/defs/enum/asc_mutex_execute_mode.html">asc_mutex_execute_mode</a>的重载，以强类型参数选择阻塞或非阻塞模式；原<code>ascMutexExecuteMode</code>类型名作为兼容别名保留。</li></ul><h3 id="公共头文件">公共头文件<a class="header-anchor" href="#公共头文件">​</a></h3><ul><li>公共头文件按<code>defs</code>、<code>utils</code>、<code>cube_compute</code>、<code>cube_datamove</code>、<code>vector_compute</code>、<code>vector_datamove</code>、<code>reg_compute</code>、<code>scalar_compute</code>、<code>atomic</code>、<code>cache_ctrl</code>、<code>sync</code>和<code>spr</code>等模块拆分，API资料同步使用最细粒度公共头文件路径。</li><li><code>c_api/asc_simd.h</code>仍作为全局聚合入口；新增<code>c_api/asc_cube.h</code>、<code>c_api/asc_memory_vector.h</code>和<code>c_api/asc_reg_vector.h</code>作为分域聚合入口。已有代码可以继续包含全局聚合头，新代码可按使用范围选择更细粒度的头文件。</li><li><a href="../../SIMD-API/c_api/defs/constant/asc_c_api_mrgsort_element_len.html">ASC_C_API_MRGSORT_ELEMENT_LEN</a>和<a href="../../SIMD-API/c_api/defs/constant/asc_vdeq_size.html">ASC_VDEQ_SIZE</a>由实现侧定义迁入公共头文件<code>c_api/defs/constant.h</code>，取值仍分别为4和16，已有接口原型中的用途不变。</li><li><a href="../../SIMD-API/c_api/defs/macro/asc_deprecation.html">ASC_DEPRECATED</a>新增至公共头文件<code>c_api/defs/macro.h</code>，用于为C API声明添加废弃属性和包含废弃版本、计划移除日期、替代接口的编译告警信息。</li><li><a href="../../SIMD-API/c_api/defs/macro/asc_is_aic-asc_is_aiv.html">ASC_IS_AIC</a>和<a href="../../SIMD-API/c_api/defs/macro/asc_is_aic-asc_is_aiv.html">ASC_IS_AIV</a>迁移至公共头文件<code>c_api/defs/macro.h</code>，用于在AIC和AIV分离模式的融合算子中隔离对应核的代码路径。</li><li>旧兼容头<code>c_api/misc/misc.h</code>、<code>c_api/utils_intf.h</code>、<code>c_api/utils/union.h</code>、<code>c_api/sys_var/sys_var.h</code>、<code>c_api/reg_compute/reg_vector.h</code>、<code>c_api/reg_compute/reg_load.h</code>和<code>c_api/reg_compute/reg_store.h</code>仍保留，但会给出废弃提示；建议迁移到对应的<code>c_api/utils/*</code>、<code>c_api/defs/*</code>、<code>c_api/reg_compute/reg_compute.h</code>或Reg搬入、搬出、聚合、离散操作的最细粒度公共头文件。</li></ul><h2 id="Bug修复">Bug修复<a class="header-anchor" href="#Bug修复">​</a></h2><ul><li>修复3510架构下<a href="../../SIMD-API/c_api/vector_datamove/asc_copy_gm2ub_align/asc_copy_gm2ub_align.html">asc_copy_gm2ub_align</a>、<a href="../../SIMD-API/c_api/vector_datamove/asc_copy_ub2gm_align/asc_copy_ub2gm_align.html">asc_copy_ub2gm_align</a>等对齐搬运接口的<code>n_burst</code>参数位宽不足问题，将相关重载的<code>n_burst</code>扩展为<code>uint32_t</code>。</li><li>修复3510架构下<a href="../../SIMD-API/c_api/reg_compute/store/asc_store.html">asc_store</a>非对齐搬出时未执行地址Post Update后处理而导致搬运结果错误的问题。</li><li>修复Post Update搬运接口的地址或地址寄存器按值传递问题：<a href="../../SIMD-API/c_api/reg_compute/load/asc_loadunalign_postupdate.html">asc_loadunalign_postupdate</a>的UB源地址、<code>addr_reg</code>偏移，以及<a href="../../SIMD-API/c_api/reg_compute/store/asc_storealign_postupdate.html">asc_storealign_postupdate</a>、<a href="../../SIMD-API/c_api/reg_compute/store/asc_storealign_1st_postupdate.html">asc_storealign_1st_postupdate</a>、<a href="../../SIMD-API/c_api/reg_compute/store/asc_storealign_pack_postupdate.html">asc_storealign_pack_postupdate</a>的UB目的地址改为引用传递，确保接口执行后的更新结果可回写调用方。</li><li>修复<a href="../../SIMD-API/c_api/reg_compute/load/asc_loadalign_postupdate.html">asc_loadalign_postupdate</a>的<code>vector_bool</code>重载缺少<code>offset</code>参数的问题，使公开声明与实现保持一致。</li><li>修复<code>vector_int4x2_t</code>的<a href="../../SIMD-API/c_api/reg_compute/load/asc_loadalign_downsample_postupdate.html">asc_loadalign_downsample_postupdate</a>和带<code>block_stride</code>、<code>repeat_stride</code>参数的<code>asc_loadalign_postupdate</code>重载只更新局部源指针副本的问题，确保连续调用时源地址更新能够回写调用方并从正确位置继续搬入。</li><li>修复<code>asc_squeeze_and_storeunalign</code>的目的矢量数据寄存器<code>dst</code>按值传递问题，改为引用传递，确保压缩结果可回写调用方。</li><li>修复2201架构下<a href="../../SIMD-API/c_api/sync/asc_sync_subblock_wait.html">asc_sync_subblock_wait</a>宏向底层接口多传<code>pipe</code>参数的问题。</li><li>修复2201架构下部分<a href="../../SIMD-API/c_api/deprecated_interface/asc_sub_relu_sync_deprecated.html">asc_sub_relu_sync</a>重载错误调用非同步实现的问题。</li><li>修复2201架构下<a href="../../SIMD-API/c_api/vector_compute/vector_arith/asc_rsqrt.html">asc_rsqrt</a>同步重载误调用非同步实现的问题。</li><li>修复<a href="../../SIMD-API/c_api/utils/sys_init/asc_init.html">asc_init</a>在3510架构下未完整复位<code>CTRL</code>、Mask、搬运循环、Padding及数据搬运原子操作类型等状态的问题，避免前序算子遗留状态影响当前算子。</li><li>修复<a href="../../SIMD-API/c_api/defs/union/asc_l13d_fmatrix_config.html">asc_l13d_fmatrix_config</a>中<code>l1_width</code>和<code>l1_height</code>字段顺序错误导致配置值与预期不一致的问题。</li><li>修复<a href="../../SIMD-API/c_api/cube_datamove/asc_copy_gm2l1/asc_copy_gm2l1.html">asc_copy_gm2l1</a>和<a href="../../SIMD-API/c_api/cube_datamove/asc_copy_l0c2l1/asc_copy_l0c2l1.html">asc_copy_l0c2l1</a>部分3510实现调用底层CCE指令时缺少参数的问题。</li><li>将标量搬出实现中的<code>ASC_C_API_DEFAULIT_OFFSET</code>拼写修正为<code>ASC_C_API_DEFAULT_OFFSET</code>。</li></ul><h2 id="接口废弃">接口废弃<a class="header-anchor" href="#接口废弃">​</a></h2><p>本版本新增以下废弃标记。完整函数原型、产品支持情况和替代链接请参见<a href="../deprecated_interface.html">废弃接口</a>。</p><table><thead><tr><th>废弃接口或重载</th><th>替代接口或迁移方式</th><th>迁移说明</th></tr></thead><tbody><tr><td><a href="../../SIMD-API/c_api/deprecated_interface/asc_set_atomic_none_deprecated.html">asc_set_atomic_none</a></td><td><code>asc_disable_dma_atomic</code></td><td>使用语义明确的原子操作关闭接口。</td></tr><tr><td><a href="../../SIMD-API/c_api/deprecated_interface/asc_set_atomic_add_int_deprecated.html">asc_set_atomic_add_int</a>、<a href="../../SIMD-API/c_api/deprecated_interface/asc_set_atomic_max_int_deprecated.html">asc_set_atomic_max_int</a>、<a href="../../SIMD-API/c_api/deprecated_interface/asc_set_atomic_min_int_deprecated.html">asc_set_atomic_min_int</a></td><td><a href="../../SIMD-API/c_api/atomic/datamove_atomic/asc_set_atomic_add.html">asc_set_atomic_add_int32</a>、<a href="../../SIMD-API/c_api/atomic/datamove_atomic/asc_set_atomic_max.html">asc_set_atomic_max_int32</a>、<a href="../../SIMD-API/c_api/atomic/datamove_atomic/asc_set_atomic_min.html">asc_set_atomic_min_int32</a></td><td>使用带明确数据类型后缀的接口。</td></tr><tr><td><a href="../../SIMD-API/c_api/deprecated_interface/asc_get_block_num_deprecated.html">asc_get_block_num</a>、<a href="../../SIMD-API/c_api/deprecated_interface/asc_get_block_idx_deprecated.html">asc_get_block_idx</a></td><td>内置变量<code>block_num</code>、<code>block_idx</code>；混合核Vector Core索引配合<a href="../../SIMD-API/c_api/utils/sys_var/asc_get_sub_block_num.html">asc_get_sub_block_num</a>和<a href="../../SIMD-API/c_api/utils/sys_var/asc_get_sub_block_id.html">asc_get_sub_block_id</a>计算</td><td>系统内置变量替代函数式查询。</td></tr><tr><td><a href="../../SIMD-API/c_api/deprecated_interface/asc_get_ar_spr_deprecated.html">asc_get_ar_spr</a>、<a href="../../SIMD-API/c_api/deprecated_interface/asc_clear_ar_spr_deprecated.html">asc_clear_ar_spr</a></td><td><code>asc_get_squeeze_status</code>、<code>asc_squeeze_and_storeunalign_init</code></td><td>使用语义明确的squeeze状态读写接口。</td></tr><tr><td><code>iter_reg</code>、<a href="../../SIMD-API/c_api/deprecated_interface/asc_create_iter_reg_deprecated.html">asc_create_iter_reg_b8</a>、<a href="../../SIMD-API/c_api/deprecated_interface/asc_create_iter_reg_deprecated.html">asc_create_iter_reg_b16</a>、<a href="../../SIMD-API/c_api/deprecated_interface/asc_create_iter_reg_deprecated.html">asc_create_iter_reg_b32</a></td><td><code>addr_reg</code>、<code>asc_update_addr_reg_b8</code>、<code>asc_update_addr_reg_b16</code>、<code>asc_update_addr_reg_b32</code></td><td>地址寄存器类型和初始化接口统一更名。</td></tr><tr><td><a href="../../SIMD-API/c_api/deprecated_interface/asc_loadalign_v1_deprecated.html">asc_loadalign_brc_v2</a>、<a href="../../SIMD-API/c_api/deprecated_interface/asc_loadalign_v1_deprecated.html">asc_loadalign_brc_v3</a>、<a href="../../SIMD-API/c_api/deprecated_interface/asc_loadalign_v1_deprecated.html">asc_loadalign_unpack_v2</a>及其Post Update重载</td><td><code>asc_loadalign_brc_datablock</code>、<code>asc_loadalign_brc_elem2datablock</code>、<code>asc_loadalign_unpack4</code>及对应Post Update接口</td><td>接口名直接表达搬入模式，避免通过版本后缀区分语义。</td></tr><tr><td><a href="../../SIMD-API/c_api/deprecated_interface/asc_storealign_v1_deprecated.html">asc_storealign_pack_v2</a>、<a href="../../SIMD-API/c_api/deprecated_interface/asc_storealign_v4_deprecated.html">asc_storealign_pack_postupdate_v2</a></td><td><code>asc_storealign_pack_quarter</code>、<code>asc_storealign_pack_quarter_postupdate</code></td><td>使用接口名明确表达四分之一宽度的pack模式。</td></tr><tr><td><a href="../../SIMD-API/c_api/deprecated_interface/asc_storeunalign_post_deprecated.html">asc_storeunalign_post</a>及部分<a href="../../SIMD-API/c_api/deprecated_interface/asc_storeunalign_postupdate_deprecated.html">asc_storeunalign_postupdate</a>旧重载</td><td><code>asc_squeeze_and_storeunalign</code>、<code>asc_squeeze_and_storeunalign_finalize</code>，或当前同名B16/B32重载</td><td>统一有效元素筛选与非对齐连续搬出流程；B8目的地址且源为<code>vector_bool</code>的重载不再推荐。</td></tr><tr><td><a href="../../SIMD-API/c_api/deprecated_interface/asc_pack_deprecated.html">asc_pack</a>、<a href="../../SIMD-API/c_api/deprecated_interface/asc_pack_deprecated.html">asc_pack_v2</a></td><td><code>asc_pack_to_low</code>、<code>asc_pack_to_high</code></td><td>使用接口名显式表达写入目的操作数的低半部分或高半部分。</td></tr><tr><td><a href="../../SIMD-API/c_api/deprecated_interface/asc_squeeze_with_status_deprecated.html">asc_squeeze_with_status</a>、<a href="../../SIMD-API/c_api/deprecated_interface/asc_squeeze_deprecated.html">asc_squeeze_v2</a></td><td><code>asc_squeeze_and_storeunalign</code>接口族，或当前<a href="../../SIMD-API/c_api/reg_compute/reg_permute_sel/asc_squeeze.html">asc_squeeze</a>重载</td><td><code>asc_squeeze_with_status</code>为本版本新增的兼容接口并同时标记废弃；<code>asc_squeeze_v2</code>在CANN 9.1.0中已经存在，本版本新增废弃标记。按是否需要连续搬出选择替代接口。</td></tr><tr><td><a href="../../SIMD-API/c_api/deprecated_interface/asc_muls_deprecated.html">asc_muls</a>、<a href="../../SIMD-API/c_api/deprecated_interface/asc_muls_deprecated.html">asc_muls_v2</a></td><td><code>asc_mul_scalar_float2half_rn</code></td><td>使用语义明确并支持显式位置参数的融合接口。</td></tr><tr><td><code>asc_exp_sub</code>、<a href="../../SIMD-API/c_api/deprecated_interface/asc_exp_sub_deprecated.html">asc_exp_sub_v2</a>的<code>half</code>转<code>float</code>重载</td><td><code>asc_exp_sub_half2float</code></td><td>使用函数名明确表达输入、输出数据类型。</td></tr><tr><td><code>asc_and</code>、<code>asc_or</code>的浮点类型重载</td><td>按相同位宽选择整数类型重载</td><td>位逻辑运算不再接受浮点矢量类型。</td></tr><tr><td>Reg类型转换中通过接口后缀或隐式规则控制源/目的位置的重载</td><td>显式传入<code>asc_position_mode</code>或<code>asc_position_quarter_mode</code>的当前同名重载</td><td>涉及<code>float</code>、<code>half</code>、<code>bfloat16_t</code>、整数、FP8、HiF8和FP4等类型转换接口；<code>_v2</code>、<code>_v3</code>、<code>_v4</code>位置后缀进入废弃期。</td></tr><tr><td><code>asc_mmad</code>、<a href="../../SIMD-API/c_api/deprecated_interface/asc_mmad_deprecated.html">asc_mmad_s4</a>、<a href="../../SIMD-API/c_api/deprecated_interface/asc_mmad_sparse_deprecated.html">asc_mmad_sparse</a>、<code>asc_mmad_mx</code>中<code>unit_flag</code>为<code>uint8_t</code>、带<code>feat_offset</code>参数的旧原型</td><td><code>unit_flag_mode</code>为<code>asc_unit_flag_mode</code>的当前同名接口</td><td>使用强类型枚举配置UnitFlag；不再传入无效的兼容参数。</td></tr><tr><td><a href="../../SIMD-API/c_api/deprecated_interface/asc_transto5hd_sync_deprecated.html">asc_transto5hd_b8_sync</a>、<a href="../../SIMD-API/c_api/deprecated_interface/asc_transto5hd_sync_deprecated.html">asc_transto5hd_b16_sync</a>、<a href="../../SIMD-API/c_api/deprecated_interface/asc_transto5hd_sync_deprecated.html">asc_transto5hd_b32_sync</a></td><td>对应的<code>asc_transto5hd_b8</code>、<code>asc_transto5hd_b16</code>、<code>asc_transto5hd_b32</code>接口分别配合<a href="../../SIMD-API/c_api/sync/asc_sync.html">asc_sync</a></td><td>将格式转换与同步操作拆分调用。</td></tr><tr><td>矩阵计算、矩阵搬运、矢量数据搬运和Memory矢量计算的<code>*_sync</code>复合接口</td><td>对应非同步接口配合<code>asc_sync()</code></td><td>包括<a href="../../SIMD-API/c_api/deprecated_interface/asc_mmad_deprecated.html">asc_mmad*_sync</a>、<a href="../deprecated_interface.html">asc_copy_*_sync</a>、<a href="../deprecated_interface.html">asc_fill_*_sync</a>和Memory矢量计算<code>*_sync</code>接口族。</td></tr><tr><td><code>asc_sync_vec</code>旧原型</td><td><code>asc_sync</code></td><td>使用统一的同步接口。</td></tr><tr><td><code>asc_copy_gm2ub_align</code>、<code>asc_copy_ub2gm_align</code>、<a href="../../SIMD-API/c_api/deprecated_interface/asc_ndim_copy_gm2ub_deprecated.html">asc_ndim_copy_gm2ub</a>中以整数参数表达L2 Cache策略的旧重载</td><td>使用<code>asc_load_l2_cache_mode</code>或<code>asc_store_l2_cache_mode</code>枚举的当前同名重载</td><td>使用强类型枚举配置L2 Cache管理策略。</td></tr></tbody></table><h2 id="文件废弃">文件废弃<a class="header-anchor" href="#文件废弃">​</a></h2><p>本版本废弃以下兼容头文件。</p><table><thead><tr><th>废弃文件</th><th>替代文件或迁移方式</th><th>迁移说明</th></tr></thead><tbody><tr><td><code>c_api/misc/misc.h</code></td><td><code>c_api/utils/sys_init.h</code>、<code>c_api/utils/sys_misc.h</code></td><td>系统初始化和其他操作接口迁移到对应的工具头文件。</td></tr><tr><td><code>c_api/utils_intf.h</code></td><td><code>c_api/defs/union.h</code>、<code>c_api/defs/enum.h</code></td><td>联合体和枚举迁移到对应的基础定义头文件。</td></tr><tr><td><code>c_api/utils/union.h</code></td><td><code>c_api/defs/union.h</code></td><td>联合体迁移到基础定义头文件。</td></tr><tr><td><code>c_api/sys_var/sys_var.h</code></td><td><code>c_api/utils/sys_var.h</code></td><td>系统资源和系统变量接口迁移到工具头文件。</td></tr><tr><td><code>c_api/reg_compute/reg_vector.h</code></td><td><code>c_api/reg_compute/reg_compute.h</code></td><td>Reg计算接口使用新的分域聚合头文件。</td></tr><tr><td><code>c_api/reg_compute/reg_load.h</code></td><td><code>c_api/reg_compute/load/loadalign.h</code>、<code>c_api/reg_compute/load/loadunalign.h</code>、<code>c_api/reg_compute/gather/ub_gather.h</code>、<code>c_api/reg_compute/compute/reg_gather.h</code>、<code>c_api/reg_compute/scatter/ub_scatter.h</code>、<code>c_api/reg_compute/compute/reg_mask.h</code>、<code>c_api/composite/loadunalign_composite.h</code></td><td>Reg对齐搬入、非对齐搬入、聚合、离散和掩码接口迁移到对应的最细粒度公共头文件。</td></tr><tr><td><code>c_api/reg_compute/reg_store.h</code></td><td><code>c_api/reg_compute/store/storealign.h</code>、<code>c_api/reg_compute/store/storeunalign.h</code>、<code>c_api/reg_compute/scatter/ub_scatter.h</code>、<code>c_api/composite/storeunalign_composite.h</code></td><td>Reg对齐搬出、非对齐搬出和离散接口迁移到对应的最细粒度公共头文件。</td></tr></tbody></table></article></div>',1)])])}const n=a(d,[["render",s]]);export{h as __pageData,n as default};
